-- ============================================================
-- Restaurant Sales Analytics Mini System - Batch Rollback Script
-- Batch ID: BATCH-2026-Q4-EXT
-- Purpose: Remove ONLY the exact 456 orders and 1195 order items
--          belonging to extension batch BATCH-2026-Q4-EXT.
-- Safety: Manifest-based identifier matching.
--         Does NOT use date filters (order_date >= ...).
--         Preserves all pre-existing records regardless of timestamps.
--         Safe for repeated/idempotent execution.
-- ============================================================

SET timezone = 'Asia/Riyadh';

BEGIN;

-- Create temporary batch manifest table for transactional isolation
CREATE TEMP TABLE IF NOT EXISTS _rollback_manifest_orders (
    order_id UUID PRIMARY KEY,
    order_number VARCHAR(50) NOT NULL
) ON COMMIT DROP;

ON CONFLICT (order_id) DO NOTHING;

-- 1. Delete associated line items belonging strictly to manifest orders
DELETE FROM order_items
WHERE order_id IN (SELECT order_id FROM _rollback_manifest_orders);

-- 2. Delete orders matching manifest order IDs and order numbers
DELETE FROM orders
WHERE id IN (SELECT order_id FROM _rollback_manifest_orders);

-- 3. Safety Gate Assertion: Verify all manifest orders have been removed
DO $$
DECLARE
    v_remaining_ext INT;
BEGIN
    SELECT COUNT(*) INTO v_remaining_ext
    FROM orders
    WHERE id IN (SELECT order_id FROM _rollback_manifest_orders);

    IF v_remaining_ext <> 0 THEN
        RAISE EXCEPTION 'Rollback Safety Gate Abort: Expected 0 remaining manifest orders, but found %', v_remaining_ext;
    END IF;
END $$;

COMMIT;

-- Rollback Verification Query
SELECT 'Batch Rollback Verification' AS check_name,
       (SELECT COUNT(*) FROM orders) AS current_total_orders,
       (SELECT COUNT(*) FROM order_items) AS current_total_items,
       (SELECT COUNT(*) FROM orders WHERE order_number LIKE 'ORD-202609%' OR order_number LIKE 'ORD-202610%' OR order_number LIKE 'ORD-202611%') AS remaining_extension_orders,
       ((SELECT COUNT(*) FROM orders) = 380 AND (SELECT COUNT(*) FROM order_items) = 968) AS exact_baseline_restored;
